const KINDS = { person: 'people', member: 'circle', med: 'meds', dose: 'doses', reading: 'readings', alert: 'alerts', refill: 'refills', message: 'messages' };
const SNAP = {};

function loadState(rows) {
  const s = emptyState(DEFAULT_SETTINGS);
  for (const r of rows) {
    if (!r || !r.rid || !r.data) continue;
    SNAP[r.rid] = r.data;
    let d = null;
    try {
      d = JSON.parse(r.data);
    } catch (e) {
      continue;
    }
    if (r.kind === 'settings') s.settings = Object.assign({}, DEFAULT_SETTINGS, d);
    else if (r.kind === 'meta') {
      s.seq = d.seq || 0;
      s.queue = d.queue || [];
      s.marks = d.marks || {};
    } else if (KINDS[r.kind]) s[KINDS[r.kind]].push(d);
  }
  s.messages.sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
  setZone(s.settings.timezone);
  return s;
}

function allRows(s) {
  const out = [
    { rid: 'settings', kind: 'settings', data: JSON.stringify(s.settings) },
    { rid: 'meta', kind: 'meta', data: JSON.stringify({ seq: s.seq, queue: s.queue, marks: s.marks }) }
  ];
  for (const kind of Object.keys(KINDS)) for (const x of s[KINDS[kind]]) out.push({ rid: x.id, kind, data: JSON.stringify(x) });
  return out;
}

function changedRows(s) {
  return allRows(s).filter(r => r.rid === 'meta' || SNAP[r.rid] !== r.data);
}

function newTexts(s, before) {
  const who = Object.fromEntries([...s.people, ...s.circle].map(w => [w.id, w]));
  return s.messages
    .filter(m => m.dir === 'out' && !before.has(m.id) && who[m.thread] && !who[m.thread].optedOut)
    .sort((a, b) => Date.parse(a.at) - Date.parse(b.at))
    .map(m => ({ to: who[m.thread].phone, body: m.body }));
}

function stateRows(name) {
  return $(name || 'Load State').all().map(i => i.json);
}



function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

