};

function buildDemo(now = Date.now(), settings = DEFAULT_SETTINGS) {
  const S = { ...DEFAULT_SETTINGS, ...settings };
  setZone(S.timezone);
  const s = emptyState(S);
  const r = rng(20261006);
  s.people = PEOPLE.map(p => ({ ...p, schedule: { ...p.schedule }, optedOut: false, aiPaused: false, paused: false, pending: null, lastReplyAt: null, unread: false }));
  s.circle = CIRCLE.map(m => ({ ...m, careFor: [...m.careFor], calls: { ...m.calls }, optedOut: false, unread: false, lastReplyAt: null }));
  s.meds = MEDS.map(m => ({ ...m, pill: { ...m.pill }, doses: { ...m.doses }, active: true, startedAt: iso(addDays(dayStart(now), -200 - Math.floor(r() * 400))) }));
  s.seq = 40;
  const today = dayStart(now);
  const WINDOW = -9;

  const weight = k => Math.round((182.1 + (k + 30) * 0.05 + (k === -9 ? 3.6 : k === -8 ? 2.4 : k === -7 ? 1.1 : 0) + (k >= -1 ? 1.1 : 0) + jitter(r, -0.6, 0.6)) * 10) / 10;
  const bp = (k, base = 132) => (k === -6 ? [168, 98] : [Math.round(base + jitter(r, -9, 10)), Math.round(81 + jitter(r, -6, 6))]);
  const sugar = k => (k === -2 ? 64 : Math.round(121 + jitter(r, -20, 24)));

  const reply = (person, phone, text, at) => inbound(s, phone, text, at, [1800, 1400]);

  for (let k = -30; k <= 0; k++) {
    const day = addDays(today, k);
    const plan = [];
    for (const p of s.people) {
      for (const slot of SLOTS) {
        const meds = slotMeds(s, p, slot.key);
        if (!meds.length) continue;
        const due = slotAt(p, slot.key, day);
        if (due > now) continue;
        plan.push({ p, slot: slot.key, due, meds });
      }
    }
    plan.sort((a, b) => a.due - b.due);
    for (const x of plan) {
      const { p, slot, due } = x;
      const d = newDose(s, p, slot, due, x.meds);
      s.doses.push(d);
      const key = p.id + ':' + k + ':' + slot;
      const sc = SCRIPT[key];
      const evening = slot === 'evening' || slot === 'bedtime';
      const roll = r();
      const missP = p.id === 'p2' ? (evening ? 0.11 : 0.04) : 0.025;
      const lateP = p.id === 'p2' ? (evening ? 0.2 : 0.1) : 0.1;
      const readMorning = slot === 'morning' && (r() < (p.id === 'p1' ? 0.86 : 0.8) || k >= -1);
      let text = pick(r, p.id === 'p1' ? ['Took them, thank you', 'Taken ✅', 'done', 'Yes taken', 'took them dear', 'All taken', 'Done 👍', 'yes'] : ['ok', 'taken', 'took em', 'Done', 'yep taken', 'ok done']);
      if (readMorning) {
        if (p.id === 'p1') {
          const [a, b] = bp(k);
          text = pick(r, ['Took them. BP ' + a + '/' + b + ', sugar ' + sugar(k), 'done. bp ' + a + '/' + b + ' sugar was ' + sugar(k), 'Taken ✅ ' + a + '/' + b + ' this morning, sugar ' + sugar(k)]);
        } else text = pick(r, ['taken. weight ' + weight(k), 'took em, ' + weight(k) + ' lbs', 'Done. Weighed ' + weight(k)]);
      } else if (p.id === 'p2' && slot === 'evening' && r() < 0.35) {
        const [a, b] = bp(k, 124);
        text = 'taken, bp ' + a + '/' + b;
      }

      if (k < WINDOW) {
        if (readMorning) {
          if (p.id === 'p1') {
            const [a, b] = bp(k);
            addReading(s, p, { type: 'bp', sys: a, dia: b }, due + 6 * MIN, 'text');
            addReading(s, p, { type: 'glucose', value: sugar(k) }, due + 6 * MIN, 'text');
          } else addReading(s, p, { type: 'weight', value: weight(k) }, due + 6 * MIN, 'text');
        }
        d.remindedAt = iso(due);
        if (roll < missP) {
          d.status = 'missed';
          d.resolvedAt = iso(due + 180 * MIN);
        } else if (roll < missP + 0.015 && x.meds.length > 1) {
          d.status = 'partial';
          d.missed = [x.meds[0].medId];
          d.takenAt = iso(due + 9 * MIN);
          d.via = 'text';
        } else {
          d.status = 'taken';
          d.via = 'text';
          d.takenAt = iso(due + (roll < missP + lateP ? jitter(r, 24, 44) : jitter(r, 2, 16)) * MIN);
          if (roll < 0.04) d.nudgedAt = iso(due + 20 * MIN);
        }
        d.resolvedAt = d.resolvedAt || d.takenAt;
        continue;
      }

      const elapsed = now - due;
      if (k === 0 && elapsed < 40 * MIN) {
        sendDose(s, d, due);
        if (elapsed >= S.nudgeMinutes * MIN) sendNudge(s, d, due + S.nudgeMinutes * MIN);
        continue;
      }
      sendDose(s, d, due);
      const at = m => Math.min(now - 30000, due + m * MIN);
      if (sc && sc.silent) {
        sendNudge(s, d, due + S.nudgeMinutes * MIN);
        escalate(s, d, due + S.escalateMinutes * MIN, 'primary');
        d.status = 'missed';
        d.resolvedAt = iso(due + S.missAfterMinutes * MIN);
        continue;
      }
      if (sc && sc.family) {
        sendNudge(s, d, due + S.nudgeMinutes * MIN);
        escalate(s, d, due + S.escalateMinutes * MIN, 'primary');
        escalate(s, d, due + S.backupMinutes * MIN, 'backup');
        const marco = memberById(s, 'm2');
        inbound(s, marco.phone, 'On it, calling Dad now', due + (S.backupMinutes + 6) * MIN);
        inbound(s, marco.phone, 'He fell asleep in his chair. He took them now, all good', due + (S.backupMinutes + 24) * MIN);
        continue;
      }
      if (sc && sc.snooze) {
        reply(p, p.phone, sc.snooze, due + sc.delay * MIN);
        const until = Date.parse(d.snoozeUntil);
        d.snoozeSent = true;
        s.messages.push({ id: uid(s, 'm'), thread: p.id, dir: 'out', author: 'ai', kind: 'dose', body: 'It’s ' + shortTime(until) + ' now, Rosa. Time for those bedtime pills. Reply TAKEN when you’ve had them.', at: iso(until), doseId: d.id, alertId: null, intent: null });
        reply(p, p.phone, sc.then, until + 3 * MIN);
        continue;
      }
      if (sc && sc.late) {
        sendNudge(s, d, due + S.nudgeMinutes * MIN);
        reply(p, p.phone, sc.late, at(sc.delay));
        continue;
      }
      if (sc && sc.reply) {
        reply(p, p.phone, sc.reply, at(sc.delay));
        const ack = SCRIPT[key + ':ack'];
        if (ack) {
          const m = memberById(s, ack.member);
          inbound(s, m.phone, ack.text, at(sc.delay + ack.delay));
        }
        continue;
      }
      if (roll < missP && k < 0 && slot !== 'bedtime') {
        sendNudge(s, d, due + S.nudgeMinutes * MIN);
        escalate(s, d, due + S.escalateMinutes * MIN, 'primary');
        const ana = memberById(s, 'm1');
        inbound(s, ana.phone, pick(r, ['On it', 'Calling now', 'ok checking']), due + (S.escalateMinutes + 4) * MIN);
        inbound(s, ana.phone, pick(r, ['Done, ' + (p.id === 'p1' ? 'she' : 'he') + ' took them', 'All good, ' + (p.id === 'p1' ? 'she' : 'he') + ' had them']), due + (S.escalateMinutes + 17) * MIN);
        continue;
      }
      if (roll < missP + lateP) {
        sendNudge(s, d, due + S.nudgeMinutes * MIN);
        reply(p, p.phone, pick(r, p.id === 'p1' ? ['Sorry, took them now', 'Oh yes! done now', 'Taken, I was on the phone'] : ['ok taken', 'took them now', 'yes done']), at(jitter(r, 24, 38)));
        continue;
      }
      reply(p, p.phone, text, at(jitter(r, 2, 16)));
    }
    if (k < WINDOW && k >= -12) {
      const anchor = atTime(day, 10);
      if (k === -10) {
        s.refills.push({ id: uid(s, 'rf'), medId: 'k2', personId: 'p1', status: 'picked', at: iso(anchor), daysLeft: 5, source: 'count', orderedAt: iso(anchor + 3 * HOUR), pickedAt: iso(addDays(anchor, 1) + 7 * HOUR), by: 'm1', alertId: null });
      }
    }
    if (k === -2) {
      const ana = memberById(s, 'm1');
      const t = atTime(day, 20, 15);
      if (t < now) inbound(s, ana.phone, 'Status?', t);
    }
  }

  for (const m of s.meds) m.supply = SUPPLY[m.id];
  const sweepAt = now >= atTime(today, S.refillHour) ? atTime(today, S.refillHour) : atTime(addDays(today, -1), S.refillHour);
  refillSweep(s, sweepAt);
  s.marks.refillDay = dayStart(sweepAt);

  for (const a of s.alerts) {
    const age = now - Date.parse(a.at);
    const keep = a.kind === 'refill' || (a.kind === 'symptom' && age < 30 * HOUR);
    if (!a.ackAt && !keep) {
      a.ackAt = iso(Date.parse(a.at) + 12 * MIN);
      a.ackBy = 'm1';
    }
    if (!a.resolvedAt && !keep && age > 6 * HOUR) {
      a.resolvedAt = iso(Date.parse(a.at) + 40 * MIN);
      a.resolution = a.resolution || 'handled';
    }
  }
  for (const p of s.people) p.unread = false;
  for (const m of s.circle) m.unread = false;
  ensureDoses(s, now);
  s.messages.sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
  return s;
}

const SCENARIOS = [
  { key: 'taken', label: 'Takes them', blurb: 'Mom gets her reminder and answers in her own words.', steps: [{ who: 'person', text: 'Took them, thank you dear' }] },
  { key: 'quiet', label: 'Goes quiet', blurb: 'No reply after the nudge, so Ana gets a text.', steps: [{ who: 'member', text: 'On it, calling her now' }, { who: 'person', text: 'Sorry! I was out in the garden. Taking them now', fresh: false, gap: 3400 }] },
  { key: 'partial', label: 'Skips one', blurb: 'Leaves one pill out and says why.', steps: [{ who: 'person', text: 'Took them but not {skip}, it upsets my stomach' }] },
  { key: 'reading', label: 'Sends a reading', blurb: 'Texts a blood pressure above the family’s limit.', steps: [{ who: 'person', text: 'Took them. My blood pressure is 172/104' }, { who: 'member', text: 'Thanks, I’ll call her' }] },
  { key: 'low', label: 'Running low', blurb: 'Says she’s almost out. Ana orders the refill.', steps: [{ who: 'person', text: 'Done. Only 3 of {low} left' }, { who: 'member', text: 'Ordered, I’ll pick it up tomorrow' }] },
  { key: 'urgent', label: 'Feels unwell', blurb: 'Describes chest symptoms. Everyone hears at once.', steps: [{ who: 'person', text: 'I feel dizzy and my chest feels tight' }, { who: 'member', text: 'On it, calling her now' }] },
  { key: 'own', label: 'Type my own', blurb: 'Reply as Mom or as Ana, however you like.', manual: true }
];

const NUMBERS = ['nudgeMinutes', 'escalateMinutes', 'backupMinutes', 'missAfterMinutes', 'quietStart', 'quietEnd', 'refillDays', 'refillHour', 'digestDay', 'digestHour', 'bpHighSys', 'bpHighDia', 'bpLowSys', 'glucoseHigh', 'glucoseLow', 'weightGainDay', 'weightGainWeek'];

const casual = (m, plural) => {
  const p = m.pill || {};
  const size = p.size === 'large' ? 'big ' : p.size === 'small' ? 'little ' : '';
  return 'the ' + size + (p.color || '') + (plural ? ' ones' : ' one');
};

const minuteOfDay = t => {
  const p = parts(t);
  return p.h * 60 + p.mi;
};

function startScenario(s, key, now) {
  const sc = SCENARIOS.find(x => x.key === key) || SCENARIOS[0];
  const S = s.settings;
  const p = s.people[0];
  const member = memberById(s, S.viewer) || s.circle[0];
  const rich = SLOTS.filter(x => slotMeds(s, p, x.key).length >= 2);
  const pool = rich.length ? rich : SLOTS.filter(x => slotMeds(s, p, x.key).length);
  if (!pool.length) throw new Error(p.name + ' has no medicines scheduled');
  const nowM = minuteOfDay(now);
  const slot = pool.slice().sort((a, b) => Math.abs(minuteOfDay(slotAt(p, a.key, now)) - nowM) - Math.abs(minuteOfDay(slotAt(p, b.key, now)) - nowM))[0];
  const day = dayStart(now);
  let d = s.doses.find(x => x.personId === p.id && x.slot === slot.key && dayStart(Date.parse(x.due)) === day);
  if (d && (d.status === 'taken' || d.status === 'partial')) {
    for (const x of d.meds) {
      if (d.missed.includes(x.medId)) continue;
      const m = medById(s, x.medId);
      if (m) m.supply += x.count;
    }
  }
  const fresh = newDose(s, p, slot.key, now, slotMeds(s, p, slot.key));
  if (d) Object.assign(d, { ...fresh, id: d.id });
  else {
    d = fresh;
    s.doses.push(d);
  }
  d.demo = true;
  s.alerts = s.alerts.filter(a => a.doseId !== d.id);
  s.messages = s.messages.filter(m => m.doseId !== d.id);
  for (const x of s.doses) {
    if (x.personId === p.id && x.id !== d.id && x.status === 'due') {
      x.status = 'taken';
      x.via = 'text';
      x.takenAt = iso(now - 60000);
      x.resolvedAt = x.takenAt;
    }
  }
  p.pending = null;
  p.optedOut = false;
  p.aiPaused = false;
  member.optedOut = false;
  const meds = d.meds.map(x => medById(s, x.medId)).filter(Boolean);
  const skipMed = meds.find(m => m.name === 'Metformin') || meds[meds.length - 1];
  const lowMed = meds.find(m => m.name === 'Metformin') || meds[0];
  if (key === 'low') {
    for (const r of s.refills) if (r.medId === lowMed.id && r.status !== 'picked') r.status = 'picked';
    lowMed.supply = Math.max(lowMed.supply, 40);
  }
  if (key === 'quiet') {
    const due = now - S.escalateMinutes * MIN + 5200;
    d.due = iso(due);
    sendDose(s, d, due);
    sendNudge(s, d, due + S.nudgeMinutes * MIN);
  } else {
    d.due = iso(now + 1400);
    sendDose(s, d, now + 1400);
  }
  const steps = (sc.steps || []).map(st => ({ ...st, text: st.text.replace('{skip}', casual(skipMed)).replace('{low}', casual(lowMed, true)) }));
  return { personId: p.id, memberId: member.id, phone: p.phone, memberPhone: member.phone, doseId: d.id, slot: slot.key, steps, since: Date.parse(d.due) - 60000 };
}

function runAction(s, action, q, now) {
  const S = s.settings;
  const person = q.person ? personById(s, q.person) : null;
  const member = q.member ? memberById(s, q.member) : null;
  const dose = q.dose ? doseById(s, q.dose) : null;
  const med = q.med ? medById(s, q.med) : null;
  const alert = q.alert ? alertById(s, q.alert) : null;
  if (q.person && !person) throw new Error('That person no longer exists');
  if (q.member && !member) throw new Error('That family member no longer exists');
  if (q.dose && !dose) throw new Error('That dose no longer exists');
  if (q.med && !med) throw new Error('That medicine no longer exists');
  if (q.alert && !alert) throw new Error('That alert no longer exists');
  const viewer = S.viewer;

  if (action === 'start') return { ok: true, ...startScenario(s, q.scenario, now) };
  if (action === 'send') {
    familyText(s, String(q.thread || ''), String(q.body || '').slice(0, 480), now, viewer);
    return { ok: true };
  }
  if (action === 'read') {
    const t = personById(s, q.thread) || memberById(s, q.thread);
    if (t) t.unread = false;
    return { ok: true };
  }
  if (action === 'pause') {
    person.aiPaused = String(q.paused) === 'true';
    note(s, person.id, person.aiPaused ? 'Automatic replies paused by the family' : 'Automatic replies back on', now);
    return { ok: true };
  }
  if (action === 'ack') {
    alert.ackAt = iso(now);
    alert.ackBy = viewer;
    return { ok: true };
  }
  if (action === 'resolve') {
    if (!alert.ackAt) {
      alert.ackAt = iso(now);
      alert.ackBy = viewer;
    }
    alert.resolvedAt = iso(now);
    alert.resolution = 'handled in the app';
    return { ok: true };
  }
  if (action === 'mark') {
    if (!['taken', 'skipped'].includes(q.status)) throw new Error('Unknown dose status');
    if (dose.status !== 'due' && dose.status !== 'scheduled' && dose.status !== 'missed') throw new Error('That dose is already settled');
    if (dose.status === 'scheduled') dose.status = 'due';
    resolveDose(s, dose, q.status, now, 'family', viewer, q.status === 'skipped' ? dose.meds.map(x => x.medId) : [], q.status === 'skipped' ? 'Marked by the family' : '');
    return { ok: true };
  }
  if (action === 'remind') {
    if (dose.status === 'scheduled') dose.due = iso(now);
    sendDose(s, dose, now, 'family');
    return { ok: true };
  }
  if (action === 'refill') {
    const r = s.refills.find(x => x.id === q.refill);
    if (!r) throw new Error('That refill no longer exists');
    const m = medById(s, r.medId);
    const a = alertById(s, r.alertId);
    if (q.status === 'ordered') {
      r.status = 'ordered';
      r.orderedAt = iso(now);
      r.by = viewer;
      if (a && !a.ackAt) {
        a.ackAt = iso(now);
        a.ackBy = viewer;
      }
    } else if (q.status === 'picked') {
      r.status = 'picked';
      r.pickedAt = iso(now);
      r.by = viewer;
      m.supply = Number(m.supply || 0) + Number(m.refillQty || 30);
      if (a) {
        a.ackAt = a.ackAt || iso(now);
        a.ackBy = a.ackBy || viewer;
        a.resolvedAt = iso(now);
        a.resolution = 'picked up';
      }
    } else throw new Error('Unknown refill status');
    return { ok: true };
  }
  if (action === 'request-refill') {
    const r = createRefill(s, med, now, 'family');
    if (!r) throw new Error('A refill for ' + med.name + ' is already in progress');
    return { ok: true };
  }
  if (action === 'supply') {
    const n = Math.round(Number(q.count));
    if (!Number.isFinite(n) || n < 0 || n > 2000) throw new Error('Enter a pill count between 0 and 2000');
    med.supply = n;
    return { ok: true, daysLeft: daysLeft(med) };
  }
  if (action === 'med-active') {
    med.active = String(q.active) === 'true';
    return { ok: true };
  }
  if (action === 'schedule') {
    if (!/^[0-2][0-9]:[0-5][0-9]$/.test(String(q.time || ''))) throw new Error('Use a time like 08:30');
    if (!SLOTS.some(x => x.key === q.slot)) throw new Error('Unknown time of day');
    person.schedule = { ...person.schedule, [q.slot]: q.time };
    const day = dayStart(now);
    for (const d of s.doses) {
      if (d.personId !== person.id || d.slot !== q.slot || d.status !== 'scheduled') continue;
      d.due = iso(slotAt(person, q.slot, Date.parse(d.due) >= day ? Date.parse(d.due) : day));
    }
    return { ok: true };
  }
  if (action === 'member') {
    for (const k of ['alerts', 'digest']) if (k in q) member[k] = String(q[k]) === 'true';
    if (q.role && ['primary', 'backup'].includes(q.role)) member.role = q.role;
    return { ok: true };
  }
  if (action === 'settings') {
    const next = { ...s.settings };
    for (const [k, v] of Object.entries(q)) {
      if (!(k in DEFAULT_SETTINGS) || k === 'viewer') continue;
      if (NUMBERS.includes(k)) next[k] = Number(v);
      else if (typeof DEFAULT_SETTINGS[k] === 'boolean') next[k] = String(v) === 'true';
      else next[k] = String(v);
    }
    s.settings = next;
    return { ok: true };
  }
  throw new Error('Unknown action ' + action);
}


function opTick(s, now) {
  return doseTick(s, now);
}

function opRefills(s, now) {
  s.marks.refillDay = dayStart(now);
  const made = refillSweep(s, now);
  return { refills: made.length };
}

const RULED = r => r.stop || r.start || r.concern === 'emergency' || r.concern === 'double';

function opPrepare(s, now, P) {
  const S = s.settings;
  const nl = String.fromCharCode(10);
  const found = whoByPhone(s, P.phone);
  if (!found || !P.text || !S.aiEnabled || found.who.aiPaused) return { useAi: false };
  const ctx = [];
  let system = [];
  if (found.kind === 'person') {
    const p = found.who;
    const meds = medsOf(s, p.id);
    const r = readCare(P.text, meds);
    if (RULED(r)) return { useAi: false };
    const dose = openDose(s, p, now);
    ctx.push('It is ' + shortTime(now) + ' where ' + firstName(p.name) + ' lives.');
    ctx.push('Their medicines: ' + meds.map(m => medLabel(m) + ' (' + pillPhrase(m) + ', for ' + m.purpose + ')').join('; ') + '.');
    if (dose) ctx.push('We just reminded them to take their ' + slotOf(dose.slot).word + ' pills: ' + dose.meds.map(x => (medById(s, x.medId) || {}).name).join(', ') + '. They have not confirmed yet.');
    else ctx.push('No dose is waiting for a reply right now.');
    const last = s.messages.filter(m => m.thread === p.id && m.dir !== 'note').slice(-6);
    if (last.length) ctx.push('Recent texts:' + nl + last.map(m => (m.dir === 'in' ? firstName(p.name) + ': ' : 'Dose Circle: ') + m.body).join(nl));
    system = [
      'You read text messages that an older adult sends to Dose Circle, a service that texts them when it is time to take their medicines and keeps their family informed.',
      'Work out what the message means. Answer with JSON only, no other text, in this shape:',
      '{"dose": "taken", "missed": [], "later_minutes": null, "reason": "", "readings": [], "low": [], "concern": "none", "question": false, "advice": false, "callback": false, "thanks": false}',
      'dose is taken, partial, skipped, later or none. partial means they took some pills but not all; list the ones they left out in missed, using the medicine name or the description they used.',
      'later means they will take them soon; later_minutes is how long, or null. reason is their own words for skipping, or an empty string.',
      'readings lists numbers they report: {"type": "bp", "sys": 0, "dia": 0, "pulse": null}, {"type": "glucose", "value": 0} or {"type": "weight", "value": 0}.',
      'low lists medicines they say are running out: {"med": "name or description", "count": number or null}.',
      'concern is emergency for chest pain, trouble breathing, a fall, stroke signs or fainting; symptom for any other way they feel unwell; otherwise none. When unsure between symptom and emergency, choose emergency.',
      'question is true when they ask something. advice is true when the question asks whether they should take, skip, mix or change a medicine. callback is true when they want someone to call or visit.',
      'Never give advice and never answer the question. Only describe the message.'
    ];
  } else {
    const m = found.who;
    if (['stop', 'start'].includes(readFamily(P.text))) return { useAi: false };
    const open = s.alerts.filter(a => a.members.includes(m.id) && !a.resolvedAt).slice(-3);
    ctx.push(firstName(m.name) + ' is family. Open alerts we texted them about: ' + (open.length ? open.map(a => a.title).join('; ') : 'none') + '.');
    system = [
      'You read text messages that family members send back to Dose Circle, a service that texts them when an older relative misses medicine, sends a worrying reading or needs a refill.',
      'Answer with JSON only, no other text: {"intent": "..."}.',
      'intent is done (the relative has taken the pills or it is sorted), ack (they are on it, calling or going over), ordered (a refill was ordered), picked (a refill was picked up), status (they ask how things are) or other.'
    ];
  }
  return { useAi: true, kind: found.kind, model: S.claudeModel || 'claude-opus-5', system_prompt: system.join(nl), user_prompt: ctx.join(nl) + nl + nl + 'New text:' + nl + P.text };
}

function opHandle(s, now, P) {
  let hint = null;
  if (P.ai) {
    let raw = '';
    if (Array.isArray(P.ai)) raw = P.ai.filter(c => c && c.type === 'text').map(c => c.text).join('');
    else if (typeof P.ai === 'string') raw = P.ai;
    try {
      const parsed = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
      const found = whoByPhone(s, P.phone);
      hint = found && found.kind === 'member' ? parsed.intent || null : parsed;
    } catch (e) {
      hint = null;
    }
  }
  const res = inbound(s, P.phone, String(P.text || '').slice(0, 480), now, [1500, 1500], hint);
  return { intent: res.intent, readBy: hint ? 'claude' : 'rules', known: !!res.who };
}

function opAction(s, now, q) {
  const action = String(q.action || '');
  let forward = null;
  let rebuilt = null;
  let result = { ok: true };
  try {
    if (action === 'sms') forward = { phone: String(q.phone || ''), text: String(q.body || '').slice(0, 480) };
    else if (action === 'reset') {
      if (!s.settings.demoMode) throw new Error('Reset only works in demo mode');
      rebuilt = buildDemo(now, s.settings);
    } else result = runAction(s, action, q, now);
  } catch (e) {
    result = { ok: false, message: e.message || 'Something went wrong' };
  }
  return { result, forward, rebuilt };
}

const call = $('Engine Called').first().json;
const op = String(call.op || '');
let P = {};
try {
  P = call.payload ? JSON.parse(call.payload) : {};
} catch (e) {
  P = {};
}
const now = Date.now();
const s = loadState(stateRows());
const before = new Set(s.messages.map(m => m.id));
let result = {};
let forward = null;
let reset = false;
let rows = null;
let texts = null;

if (!s.people.length && op !== 'reset' && !(op === 'action' && P.action === 'reset')) {
  result = { ok: false, message: 'No family yet. Run the Demo Family workflow first.' };
  rows = [];
  texts = [];
} else if (op === 'tick') result = opTick(s, now);
else if (op === 'refills') result = opRefills(s, now);
else if (op === 'prepare') result = opPrepare(s, now, P);
else if (op === 'handle') result = opHandle(s, now, P);
else if (op === 'digest') result = weeklyDigest(s, now);
else if (op === 'read') result = publicState(s, now);
else if (op === 'action') {
  const a = opAction(s, now, P);
  result = a.result;
  forward = a.forward;
  if (a.rebuilt) {
    reset = true;
    rows = allRows(a.rebuilt);
    texts = [];
  }
} else if (op === 'reset') {
  reset = true;
  rows = allRows(buildDemo(now, s.settings));
  texts = [];
  result = { ok: true };
} else result = { ok: false, message: 'Unknown operation ' + op };

const S = s.settings;
return [{ json: {
  op,
  result,
  rows: rows || changedRows(s),
  texts: texts || newTexts(s, before),
  forward,
  reset,
  send: !S.demoMode,
  from: S.textingNumber
} }];

const r = Object.assign({}, $('Run Engine').first().json);
delete r.rows;
return [{ json: r }];
